// Real CaptureEmitter -> named pipe -> unmodified Worker --fixture -> DPAPI
// ContentStore. Only a freshly created PrivateInputDev/fixtures directory and
// isolated suffix are used. No installed profile, production queue or text.
#include "../../activity/CaptureIPC.h"
#include "../../activity/LearningIPC.h"
#include "../../activity/Platform.h"
#include "SyntheticSnapshot.h"
#include <iostream>
#include <memory>
#include <future>
#include <thread>
using namespace private_input::activity;
namespace fs=std::filesystem;
static void pump(unsigned ms){auto end=GetTickCount64()+ms;MSG m{};while(GetTickCount64()<end){while(PeekMessageW(&m,nullptr,0,0,PM_REMOVE)){TranslateMessage(&m);DispatchMessageW(&m);}Sleep(10);}}
int wmain(int argc,wchar_t**argv){Json out=Json::object({{"isolatedSuffix",true},{"productionDataRead",false},{"directStoreWrite",false},{"syntheticTermOnly",true}});PROCESS_INFORMATION child{};fs::path root;std::wstring suffix,windowClass;std::unique_ptr<CaptureEmitter>emitter;
 try{const bool queueOnly=argc==4&&std::wstring(argv[3])==L"--queue-contention-only";require((argc==3||queueOnly)&&std::wstring(argv[1])==L"--authorized-isolated-pipe","explicit isolated fixture authorization required");require(SUCCEEDED(CoInitializeEx(nullptr,COINIT_APARTMENTTHREADED)),"COM");require(fs::is_regular_file(argv[2]),"existing worker binary required");auto name=L"pipe-"+wide(uuidText(newId()));root=userRoot().parent_path()/L"PrivateInputDev"/L"fixtures"/name;fs::create_directories(root.parent_path());require(!fs::exists(root)&&fs::create_directory(root),"fresh isolated fixture directory");suffix=L"fixture."+name;windowClass=L"LingheInput.Activity."+suffix;out["fixtureDirectory"]=utf8(root.wstring());
 auto command=L"\""+fs::absolute(argv[2]).wstring()+L"\" --fixture \""+root.wstring()+L"\"";STARTUPINFOW startup{};startup.cb=sizeof(startup);require(CreateProcessW(fs::absolute(argv[2]).c_str(),command.data(),nullptr,nullptr,FALSE,0,nullptr,nullptr,&startup,&child)!=FALSE,"isolated worker launch");CloseHandle(child.hThread);child.hThread=nullptr;
 auto ready=[&]{HANDLE h=OpenFileMappingW(FILE_MAP_READ,FALSE,(learningName(suffix)+LearningIntentGateSuffix).c_str());if(!h)return false;auto*v=static_cast<const LearningIntentGate*>(MapViewOfFile(h,FILE_MAP_READ,0,0,sizeof(LearningIntentGate)));bool okay=v&&v->magic==LearningIntentGateMagic&&v->enabled&&hasLearningIntentID(v->token);if(v)UnmapViewOfFile(v);CloseHandle(h);return okay;};auto until=GetTickCount64()+10000;while(!ready()&&GetTickCount64()<until&&WaitForSingleObject(child.hProcess,0)==WAIT_TIMEOUT)pump(50);require(ready(),"isolated learning gate not ready");out["workerGateReady"]=true;
 auto row=[&](){auto file=root/L"isolated-device"/L"content-v1.dpapi";if(!fs::exists(file))return Json();try{auto state=syntheticSnapshot(file);for(const auto&e:state.at("archive").at("entries").items)if(e.at("reading").str()=="he cheng"&&e.at("text").str()=="合成")return e;}catch(...){}return Json();};
 emitter=std::make_unique<CaptureEmitter>(suffix);emitter->start();LearningCapability capability;require(emitter->emitLearning(L"he cheng",L"合成",nullptr,3,&capability),"initial seed enqueue");until=GetTickCount64()+10000;Json value;while(GetTickCount64()<until){value=row();if(value.kind==Json::Kind::object)break;pump(50);}require(value.kind==Json::Kind::object&&!value.at("deleted").boolean(),"real kind3 did not persist");out["kind3Persisted"]=true;
 auto waitDelivery=[&](const std::shared_ptr<LearningForgetRequest>&request,unsigned timeout){auto end=GetTickCount64()+timeout;while(!request->delivery->complete.load()&&GetTickCount64()<end)pump(25);require(request->delivery->complete.load(),"explicit forget completion timeout");return request->delivery->status.load();};
 auto request=emitter->makeForget(L"he cheng",L"合成",capability);auto stale=emitter->makeForget(L"jiu quan xian",L"旧授权",capability);require(request&&stale,"bound explicit requests");
 std::promise<void> queueLocked,releaseQueue;auto release=releaseQueue.get_future();std::thread locker([&]{emitter->withQueueLockForTest([&]{queueLocked.set_value();release.wait();});});queueLocked.get_future().wait();bool busyResult=emitter->sendForget(request);releaseQueue.set_value();locker.join();require(!busyResult&&request->delivery->complete.load()&&request->delivery->status.load()==LearningIntentStatus::Retry,"queue contention must be visible retry");out["queueBusyVisibleRetry"]=true;
 if(queueOnly){out["passed"]=true;}else{
 auto gateHandle=OpenFileMappingW(FILE_MAP_READ|FILE_MAP_WRITE,FALSE,(learningName(suffix)+LearningIntentGateSuffix).c_str());require(gateHandle!=nullptr,"own fixture gate");auto*gate=static_cast<LearningIntentGate*>(MapViewOfFile(gateHandle,FILE_MAP_READ|FILE_MAP_WRITE,0,0,sizeof(LearningIntentGate)));require(gate!=nullptr,"own fixture gate view");InterlockedExchange(reinterpret_cast<volatile LONG*>(&gate->enabled),0);
 require(emitter->sendForget(request),"bound forget enqueue while publication gate closed");auto status=waitDelivery(request,10000);until=GetTickCount64()+10000;while(!ready()&&GetTickCount64()<until)pump(25);require(ready(),"Worker republishes its own gate after commit");UnmapViewOfFile(gate);CloseHandle(gateHandle);require(status==LearningIntentStatus::Applied||status==LearningIntentStatus::Duplicate,"closed publication gate must not discard bound intent");out["closedGateDurableACK"]=true;
 value=row();require(value.kind==Json::Kind::object&&value.at("deleted").boolean()&&value.at("generation").num()==1,"first explicit tombstone persisted");out["kind12Persisted"]=true;
 require(emitter->sendForget(request),"same event retry enqueue");require(waitDelivery(request,10000)==LearningIntentStatus::Duplicate&&row().at("generation").num()==1,"same event cannot advance deletion twice");out["sameEventIdempotent"]=true;auto conflict=std::make_shared<LearningForgetRequest>(request->capability,request->event,request->createdAt,L"he cheng",L"不同合成");require(emitter->sendForget(conflict),"conflicting immutable event test enqueue");require(waitDelivery(conflict,10000)==LearningIntentStatus::Invalid&&row().at("generation").num()==1,"cached event must bind immutable payload");out["conflictingPayloadRejected"]=true;
 require(emitter->sendForget(stale),"stale bound enqueue");require(waitDelivery(stale,10000)==LearningIntentStatus::Stale,"actual Worker token rotation must reject old authority");out["rotatedAuthorityRejected"]=true;
 // Capture a new capability from a real fresh committed selection, then lose
 // the Worker. Only the explicit request outlives its emitter owner.
 require(emitter->emitLearning(L"he cheng",L"合成",nullptr,3,&capability),"relearn seed enqueue");until=GetTickCount64()+10000;while(GetTickCount64()<until){value=row();if(!value.at("deleted").boolean()&&value.at("generation").num()==2)break;pump(25);}require(!value.at("deleted").boolean()&&value.at("generation").num()==2,"relearn before disconnect");require(capability.generation==request->capability.generation&&capability.token!=request->capability.token,"same scope generation with actually rotated token");out["sameGenerationDifferentTokenRejected"]=true;
 auto workerWindow=FindWindowW(windowClass.c_str(),nullptr);DWORD workerPid=0;if(workerWindow)GetWindowThreadProcessId(workerWindow,&workerPid);require(workerWindow&&workerPid==child.dwProcessId,"owned worker window");PostMessageW(workerWindow,WM_APP+99,0,0);require(WaitForSingleObject(child.hProcess,12000)==WAIT_OBJECT_0,"fixture worker natural stop before offline test");CloseHandle(child.hProcess);child.hProcess=nullptr;
 auto offlineRequest=emitter->makeForget(L"he cheng",L"合成",capability);require(emitter->sendForget(offlineRequest),"offline explicit enqueue");auto destruction=GetTickCount64();emitter.reset();require(GetTickCount64()-destruction<100,"emitter owner exit must not block");require(waitDelivery(offlineRequest,33000)==LearningIntentStatus::Retry,"offline timeout must surface retry rather than success");out["ownerExitNonblocking"]=true;out["offlineTimeoutVisible"]=true;
 // Same request/event/time/capability, after the real 30s transport timeout.
 require(CreateProcessW(fs::absolute(argv[2]).c_str(),command.data(),nullptr,nullptr,FALSE,0,nullptr,nullptr,&startup,&child)!=FALSE,"isolated worker restart");CloseHandle(child.hThread);child.hThread=nullptr;until=GetTickCount64()+10000;while(!ready()&&GetTickCount64()<until)pump(25);require(ready(),"restarted fixture gate");emitter=std::make_unique<CaptureEmitter>(suffix);emitter->start();require(emitter->sendForget(offlineRequest),"manual same-event retry after recovery");status=waitDelivery(offlineRequest,10000);require(status==LearningIntentStatus::Applied||status==LearningIntentStatus::Duplicate,"recovered same-event ACK");value=row();require(value.at("deleted").boolean()&&value.at("generation").num()==3,"recovered explicit intent applies exactly once");require(emitter->sendForget(offlineRequest),"retry recovered receipt");require(waitDelivery(offlineRequest,10000)==LearningIntentStatus::Duplicate&&row().at("generation").num()==3,"recovered retry remains idempotent");out["offlineRecoverySameEvent"]=true;out["generation"]=3;out["passed"]=true;}
 }catch(const std::exception&e){out["passed"]=false;out["errorClass"]=std::string(e.what());}
 emitter.reset();pump(100);if(child.hProcess){auto window=FindWindowW(windowClass.c_str(),nullptr);DWORD pid=0;if(window)GetWindowThreadProcessId(window,&pid);if(window&&pid==child.dwProcessId)PostMessageW(window,WM_APP+99,0,0);auto exit=WaitForSingleObject(child.hProcess,12000);out["isolatedWorkerStopped"]=exit==WAIT_OBJECT_0;if(exit!=WAIT_OBJECT_0)out["passed"]=false;CloseHandle(child.hProcess);}CoUninitialize();std::cout<<out.dump()<<'\n';return out.at("passed").boolean()?0:1;}
